const b = $('Webhook').first().json.body || {};
const hdr = $('Webhook').first().json.headers || {};
const raw = (b.token || hdr.authorization || '').replace(/^Bearer\s+/i, '');
let userId = '', role = '';
try {
  const response = await fetch('{{ $env.SUPABASE_URL || "https://VOTRE-PROJET-SUPABASE.supabase.co" }}/auth/v1/user', {
    headers: { Authorization: `Bearer ${raw}`, apikey: '{{ $env.SUPABASE_ANON_KEY || "VOTRE_SUPABASE_ANON_KEY" }}' }
  });
  if (!response.ok) throw new Error('Token invalid');
  const user = await response.json();
  userId = user.id || '';
  role = (user.user_metadata && user.user_metadata.role) || (user.app_metadata && user.app_metadata.role) || '';
} catch (e) {}
const valid = !!userId && ['owner', 'proprietaire', 'proprio'].includes(String(role).toLowerCase());
return [{ json: { userId, role, token: raw, sessionId: b.sessionid || ('owner-' + userId), userMessage: b.message || '', valid: valid ? 'true' : 'false' } }];

const auth = $('Code - Auth JWT').first().json;
let historyText = '';
try {
  const mem = $('Get Long-Term Memory').first().json;
  const rows = Array.isArray(mem) ? mem : (mem?.conversation_data ? mem : []);
  historyText = (Array.isArray(rows) ? rows : [rows]).map(r => {
    const cd = r.conversation_data || r;
    return `Proprio: ${cd.user || ''}\nKayvibot: ${cd.assistant || ''}`;
  }).join('\n');
} catch {}

let gbrainText = '';
try { gbrainText = JSON.stringify($('gbrain Recall').first().json); } catch {}

let ownerContext = {};
try { ownerContext = $('Fetch Owner Context').first().json.context || $('Fetch Owner Context').first().json; } catch {}

const alertes = JSON.stringify(ownerContext.alerts || []);
const portfolio = JSON.stringify(ownerContext.portfolio || {});

const systemMessage = `Tu es le copilote d'un propriétaire de villa sur Kayvila.

HISTORIQUE :
${historyText || 'Aucun historique'}

MÉMOIRE SÉMANTIQUE (gbrain — décisions et contexte passés) :
${gbrainText || 'Aucune'}

DONNÉES COMPLÈTES DU PROPRIÉTAIRE (portfolio, villas, bookings, stats, tâches, OTA, alertes) :
${JSON.stringify(ownerContext, null, 2)}

ALERTES PROACTIVES (B1 — 5 types calculés live) :
${alertes}
⚠️ OUVRE la conversation en présentant ces alertes au propriétaire avant toute question. Priorise : 🔴 conflits > tâches en retard > trous calendrier > OTA > revenu.

MESSAGE PROPRIÉTAIRE : ${auth.userMessage}
DATE : ${new Date().toLocaleDateString('fr-FR', { timeZone: 'America/Martinique' })}

SOURCE DE VÉRITÉ : les DONNÉES CI-DESSUS. Tu n'as pas d'outils externes. Utilise UNIQUEMENT ce qui est fourni dans ce contexte.

TON RÔLE :
- OUVRIR par les alertes proactives (les 5 types) avant toute question du propriétaire
- Répondre aux questions business du propriétaire
- Lui donner des insights sur ses performances
- L'alerter sur les problèmes (tâches en retard, conflits de réservation)
- Ne JAMAIS modifier une réservation ou un prix sans confirmation explicite

TON TON :
- Respectueux et direct
- Créole bienvenu si le proprio l'utilise
- Toujours sourcer les chiffres ("Selon ton dashboard...")

CAPACITÉS :
- "Combien j'ai gagné ce mois-ci ?" → chiffres + comparer au mois précédent
- "Qui arrive cette semaine ?" → liste des check-ins avec détails
- "La villa Corail est dispo en juillet ?" → vérifier le calendrier
- "Tâches en retard ?" → lister avec priorité
- "Comment va la synchro Airbnb ?" → diagnostiquer

RÈGLES :
- Ne contacter un client qu'avec validation explicite
- Ne jamais modifier les prix
- Alerter proactivement si problème détecté`;

return { json: { sessionId: auth.sessionId, userId: auth.userId, userMessage: auth.userMessage, systemMessage } };

const i = $input.first().json;
let t = i.output || i.text || "Désolé, je rencontre un souci technique.";
t = t.replace(/\*\*(.*?)\*\*/g, '$1').replace(/^[ \t]*#+[ \t]+/gm, '').replace(/^[ \t]*-+[ \t]+/gm, '• ').trim();
return [{ json: { response: t, sessionId: $('Code - Auth JWT').first().json.sessionId, userId: $('Code - Auth JWT').first().json.userId } }];

const msg = ($('Code - Auth JWT').first().json.userMessage || '').toLowerCase();
const urgentKw = ['urgent', 'retard', 'annul', 'conflit', 'problème', 'probleme', 'panne', 'litige', 'check-in', 'checkin', 'aujourd', 'ce soir', 'demain', 'ménage pas fait', 'menage pas fait'];
const isUrgent = urgentKw.some(k => msg.includes(k));
return [{ json: { isUrgent: isUrgent ? 'true' : 'false', userId: $('Code - Auth JWT').first().json.userId, message: $('Code - Auth JWT').first().json.userMessage, aiOutput: ($('AI Agent DeepSeek').first().json.output || '') } }];

